   102	    }
   103	
   104	    // MARK: - The pipeline
   105	
   106	    /// The mix's share first, then each stem's: `(finished + current) / (1 + N)`.
   107	    var progress: Double {
   108	        lock.lock()
   109	        defer { lock.unlock() }
   110	        let running = current?.progress ?? 0
   111	        return (Double(finishedCount) + running) / Double(1 + stems.count)
   112	    }
   113	
   114	    /// The loudness gain is the mix's alone (spec §11 AU-108 (e)).
   115	    func normalizeAudio(byLinearGain gain: Float) {
   116	        mix.normalizeAudio(byLinearGain: gain)
   117	    }
   118	
   119	    func start(completion: @escaping (Result<URL, any Error>) -> Void) {
   120	        self.completion = completion
   121	        mix.start { [weak self] result in self?.ended(result, at: self?.mixURL, next: 0) }
   122	    }
   123	
   124	    /// Sets the flag and stops the write running now; a stem not yet started
   125	    /// sees the flag before it starts.
   126	    func cancel() {
   127	        lock.lock()
   128	        cancelRequested = true
   129	        let running = current
   130	        lock.unlock()
   131	        running?.cancel()
   132	    }
   133	
   134	    private var isCancelled: Bool {
   135	        lock.lock()
   136	        defer { lock.unlock() }
   137	        return cancelRequested
   138	    }
   139	
   140	    /// One write ended (main thread): on success the file is kept and stem
   141	    /// `next` follows; otherwise the job ends with nothing left behind.
   142	    private func ended(_ result: Result<URL, any Error>, at url: URL?, next: Int) {
   143	        lock.lock()
   144	        current = nil
   145	        lock.unlock()
   146	        switch result {
   147	        case .failure(let error):
   148	            if let url { written.append(url) }
   149	            fail(error)
   150	        case .success:
   151	            if let url { written.append(url) }
   152	            lock.lock()
   153	            finishedCount += 1
   154	            lock.unlock()
   155	            write(next)
   156	        }
   157	    }
   158	
   159	    /// Builds stem `index` on the queue, then writes it on the main thread.
   160	    private func write(_ index: Int) {
   161	        guard !isCancelled else { return fail(Exporter.ExportError.cancelled) }
   162	        guard index < stems.count else { return complete(.success(mixURL)) }
   163	        let stem = stems[index]
   164	        queue.async { [weak self] in
   165	            guard let self else { return }
   166	            let built = Result { try self.rebuild().selectingAudio(of: Set(stem.tracks)) }
   167	            DispatchQueue.main.async { self.writeBuilt(built, stem: stem, index: index) }
   168	        }
   169	    }
   170	
   171	    private func writeBuilt(_ built: Result<BuiltComposition, any Error>, stem: ExportStem, index: Int) {
   172	        guard !isCancelled else { return fail(Exporter.ExportError.cancelled) }
   173	        let url = Self.url(for: stem, mix: mixURL)
   174	        let writer: ExportWriter
   175	        do {
   176	            let composition = try built.get()
   177	            // The save panel asked about the mix; a stem's file is replaced.
   178	            try? FileManager.default.removeItem(at: url)
   179	            writer = try ExportWriter(built: composition, settings: settings, chapters: [], to: url)
   180	        } catch {
   181	            return fail(error)
   182	        }
   183	        lock.lock()
   184	        current = writer
   185	        let cancelled = cancelRequested
   186	        lock.unlock()
   187	        if cancelled { writer.cancel() }
   188	        writer.start { [weak self] result in self?.ended(result, at: url, next: index + 1) }
   189	    }
   190	
   191	    /// Removes every file this job wrote, then reports `error`.
   192	    private func fail(_ error: any Error) {
   193	        for url in written { try? FileManager.default.removeItem(at: url) }
   194	        written = []
   195	        complete(.failure(error))
   196	    }
   197	
   198	    private func complete(_ result: Result<URL, any Error>) {
   199	        let handler = completion
   200	        completion = nil
   201	        handler?(result)
   202	    }
   203	}
