  3	/// The export's and the offline frame's wait for the masks they draw (road map creator-jobs
  4	/// CO2b, spec §11 CO-6, CO-22 (e), (f); a picture's, CO10b, CO-106), in `withRampAudio`'s
  5	/// shape: wanted on the lane before the build, so no frame is composed while a mask it draws is
  6	/// still being made.
  7	/// Both share every owner's open masks jobs by CO-22 (c)'s keep rule rather than queueing a
  8	/// second one behind the document's.
  9	///
 10	/// **Deadlock.** `AnalysisLane.wait` asks `cancelled()` under the lane's lock, and an
 11	/// `Exporter`'s last reference can drop there; `releaseMasks` therefore runs inside
 12	/// `releaseRecipeKey`'s `ramp` closure, which `deinit` defers (as `RampAudioRenders.release`).
 13	/// No owner's `alive` here takes a lock.
 14	extension Exporter {
 15	    /// How long `render_frame` and File ▸ Save Frame… wait for a frame's masks (CO-6).
 16	    static let frameCutoutWait: TimeInterval = 30
 17	
 18	    private static let maskOwnersLock = NSLock()
 19	    /// An export's recipe key → its lane owner, made at its first want.
 20	    private static var maskOwners: [Int: Int] = [:]
 21	
 22	    /// The lane owner of the export writing under `key`, made on first use.
 23	    private static func maskOwner(for key: Int) -> Int {
 24	        maskOwnersLock.lock()
 25	        defer { maskOwnersLock.unlock() }
 26	        if let owner = maskOwners[key] { return owner }
 27	        let owner = AnalysisLane.shared.newOwner()
 28	        maskOwners[key] = owner
 29	        return owner
 30	    }
 31	
 32	    /// Blocks until every mask the export's range draws is cached (CO-22 (e)): the windows of
 33	    /// `plan`'s cut-out clips over `settings`' range, and of the cut pictures meeting it (CO-106),
 34	    /// wanted under the export's own owner — the open jobs it shares plus the remainder, kind by
 35	    /// kind — and waited on with no deadline but `cancelled`. No cache folder, an unreadable
 36	    /// media or a failed job throws `cutoutFailed` naming the first window's clip of that media
 37	    /// and kind (`foreground:` from that kind); a media still missing after a second landing too.
 38	    /// Never main.
 39	    static func waitForMasks(
 40	        plan: CompositionPlan, urls: [UInt32: URL], settings: ExportSettings, key: Int,
 41	        cancelled: @escaping () -> Bool
 42	    ) throws {
 43	        guard let project = RecipeSource.shared.project(for: key) else { return }
 44	        let snapshot = project.snapshot
 45	        let range = settings.start..<(settings.start + max(settings.duration, 0))
 46	        let windows = CutoutWants.windows(plan: plan, snapshot: snapshot, range: range)
 47	            + CutoutWants.imageWindows(snapshot: snapshot, range: range)
 48	        guard let first = windows.first(where: { urls[$0.media] != nil }) else { return }
 49	        func clip(of media: UInt32, kind: AnalysisKind) -> UInt32 {
 50	            windows.first { $0.media == media && $0.kind == kind }?.clip ?? first.clip
 51	        }
 52	        guard let cacheDir = ReverseSource.shared.resolution(for: key).cache else {
 53	            throw ExportError.cutoutFailed(
 54	                clip: first.clip, message: "the project has no cache folder to keep the analysis in",
 55	                foreground: first.kind == .foreground)
 56	        }
 57	        let owner = maskOwner(for: key)
 58	        var landings = 0
 59	        while true {
 60	            let (requests, failures) = CutoutWants.wants(
 61	                windows: windows, snapshot: snapshot, urls: urls, cacheDir: cacheDir)
 62	            if let failure = failures.first {
 63	                let kind = windows.first { $0.clip == failure.clip }?.kind ?? .masks
 64	                throw ExportError.cutoutFailed(
 65	                    clip: failure.clip, message: failure.message, foreground: kind == .foreground)
 66	            }
 67	            guard let missing = requests.first else { return }
 68	            if landings >= 2 {
 69	                throw ExportError.cutoutFailed(
 70	                    clip: clip(of: missing.media.id, kind: missing.kind),
 71	                    message: "its masks do not cover the frames it plays",
 72	                    foreground: missing.kind == .foreground)
 73	            }
 74	            AnalysisLane.shared.want(requests, owner: owner, alive: { true }, settled: nil)
 75	            #if FRAMEJOB_DEV_TOOLS
 76	            CutoutWants.log(.export, owner: owner, requests)
 77	            #endif
 78	            switch AnalysisLane.shared.wait(
 79	                for: requests, owner: owner, deadline: .distantFuture, cancelled: cancelled)
 80	            {
 81	            case .landed:
 82	                landings += 1
 83	            case .failed(let why):
 84	                let failed = requests.first {
 85	                    if case .failed? = AnalysisLane.shared.run(of: $0)?.outcome { return true }
 86	                    return false
 87	                } ?? missing
 88	                throw ExportError.cutoutFailed(
 89	                    clip: clip(of: failed.media.id, kind: failed.kind), message: why,
 90	                    foreground: failed.kind == .foreground)
 91	            case .cancelled, .timedOut:
 92	                throw ExportError.cancelled
 93	            }
 94	        }
 95	    }
 96	
 97	    /// Drops the export's mask wants (CO-22 (e)); from `releaseRecipeKey`'s `ramp` closure.
 98	    static func releaseMasks(key: Int) {
 99	        maskOwnersLock.lock()
100	        let owner = maskOwners.removeValue(forKey: key)
101	        maskOwnersLock.unlock()
102	        if let owner { AnalysisLane.shared.release(owner: owner) }
103	    }
