105	    /// A media's masks of one kind: the frame wait's stamps and uncovered set are keyed by it.
106	    private struct MaskKey: Hashable {
107	        let kind: AnalysisKind
108	        let media: UInt32
109	    }
110	
111	    /// Waits up to `limit` for the masks the recipe at `t` draws (CO-22 (f)) under a fresh owner,
112	    /// polling the store every `AnalysisLane.pollInterval` until each is covered, one of its
113	    /// requests failed, or the limit; answers the clips drawn uncut, ascending — an unreadable
114	    /// media's at once, every one with no cache folder. A cut picture's masks are waited for by
115	    /// their kind beside the movies' (CO-106). Never main: it blocks.
116	    static func waitForFrameMasks(
117	        project: ReelProject, urls: [UInt32: URL], key: Int, at t: Ticks,
118	        options: RecipeOptions, limit: TimeInterval
119	    ) -> [UInt32] {
120	        let windows = CutoutWants.frameWindows(project: project, at: t, options: options)
121	            .filter { urls[$0.media] != nil }
122	        guard !windows.isEmpty else { return [] }
123	        let snapshot = project.snapshot
124	        func clips(of keys: Set<MaskKey>) -> [UInt32] {
125	            Array(Set(windows.filter { keys.contains(MaskKey(kind: $0.kind, media: $0.media)) }
126	                .map(\.clip))).sorted()
127	        }
128	        guard let cacheDir = ReverseSource.shared.resolution(for: key).cache else {
129	            return clips(of: Set(windows.map { MaskKey(kind: $0.kind, media: $0.media) }))
130	        }
131	        var needs: [MaskKey: [ClosedRange<Int>]] = [:]
132	        for kind in Set(windows.map(\.kind)) {
133	            let byMedia = CutoutWants.needs(
134	                windows: windows.filter { $0.kind == kind }, snapshot: snapshot, urls: urls)
135	            for (media, need) in byMedia { needs[MaskKey(kind: kind, media: media)] = need }
136	        }
137	        let (requests, failures) = CutoutWants.wants(
138	            windows: windows, snapshot: snapshot, urls: urls, cacheDir: cacheDir)
139	        let unreadable = Set(failures.compactMap { failure in
140	            windows.first { $0.clip == failure.clip }.map { MaskKey(kind: $0.kind, media: $0.media) }
141	        })
142	        guard !requests.isEmpty else { return clips(of: unreadable) }
143	        // Each waited media's stamp, made once by its request; the polls only look up.
144	        var stamps: [MaskKey: AnalysisStamp] = [:]
145	        for request in requests {
146	            stamps[MaskKey(kind: request.kind, media: request.media.id)] = request.stamp
147	        }
148	        func uncovered() -> Set<MaskKey> {
149	            Set(stamps.filter { key, stamp in
150	                (needs[key] ?? []).contains {
151	                    if case .hit = AnalysisStore.lookup(
152	                        key.kind, media: key.media, stamp: stamp, need: $0, in: cacheDir)
153	                    {
154	                        return false
155	                    }
156	                    return true
157	                }
158	            }.keys)
159	        }
160	        let owner = AnalysisLane.shared.newOwner()
161	        defer { AnalysisLane.shared.release(owner: owner) }
162	        AnalysisLane.shared.want(requests, owner: owner, alive: { true }, settled: nil)
163	        #if FRAMEJOB_DEV_TOOLS
164	        CutoutWants.log(.frame, owner: owner, requests)
165	        #endif
166	        let deadline = Date().addingTimeInterval(limit)
167	        var missing = uncovered()
168	        while !missing.isEmpty, Date() < deadline,
169	            !requests.contains(where: {
170	                if case .failed? = AnalysisLane.shared.run(of: $0)?.outcome { return true }
171	                return false
172	            })
173	        {
174	            Thread.sleep(forTimeInterval: AnalysisLane.pollInterval)
175	            missing = uncovered()
176	        }
177	        return clips(of: missing.union(unreadable))
178	    }
179	
180	    /// `render_frame`'s sentence for each clip drawn uncut (CO-22 (f)), ascending: a picture
181	    /// cut by its foreground (in `foreground`) names its foreground masks (CO-106).
182	    static func cutoutSentences(_ uncut: [UInt32], foreground: Set<UInt32> = []) -> [String] {
183	        uncut.sorted().map {
184	            "Clip \($0) is drawn uncut: its \(foreground.contains($0) ? "foreground" : "person") "
185	                + "masks were not ready within \(Int(frameCutoutWait)) s."
186	        }
187	    }
188	}
