  3	/// The export's wait for its offline audio renders (spec §11 SR-12 (h),
  4	/// AU-57, AU-147), before the composition is built: a ramp segment's render,
  5	/// a clip window's isolated voice, or its voice effect, is READY only when
  6	/// its file exists as the build runs, and an export never writes a ramp
  7	/// silent, an isolated clip dry or a voiced clip without its effect. First,
  8	/// a gated or de-essed clip's measured loudness (AU-42).
  9	extension Exporter {
 10	    /// Runs `build` once every renderable ramp segment, isolated window and
 11	    /// voiced window of `plan` has its file, wanting them under this export's
 12	    /// `key` meanwhile (released by `releaseRecipeKey`, from `finish` and
 13	    /// `deinit`). An image sequence has no sound and does not wait; a plan
 14	    /// with none builds at once. A ramp segment with no cache folder to
 15	    /// render into, or a render that failed, fails the export
 16	    /// `rampAudioFailed`; an isolated window the same way fails it
 17	    /// `isolationFailed`, a voiced one `voiceFailed`; `cancelled()` answering
 18	    /// true fails it `cancelled`. The voices are wanted in a second wait,
 19	    /// after the first: a voice over an isolated clip is rendered from that
 20	    /// clip's isolated file (AU-143), so its request exists only once that
 21	    /// file does.
 22	    /// The sheet reads "Preparing…" throughout. On `buildQueue`, never main.
 23	    static func withRampAudio<T>(
 24	        plan: CompositionPlan, urls: [UInt32: URL], settings: ExportSettings, key: Int,
 25	        cancelled: @escaping () -> Bool, then build: () throws -> T
 26	    ) throws -> T {
 27	        // Every mask the range draws first (spec §11 CO-22 (e)): a GIF or APNG waits too.
 28	        try waitForMasks(plan: plan, urls: urls, settings: settings, key: key, cancelled: cancelled)
 29	        guard !settings.isImageSequence else { return try build() }
 30	        return try withOfflineAudio(
 31	            plan: plan, urls: urls, key: key, cancelled: cancelled, then: build)
 32	    }
 33	
 34	    /// `withRampAudio`'s waits for a composition that has sound: the levels,
 35	    /// then the ramp, isolation and voice renders, each wanted under `key`.
 36	    /// The export calls it through `withRampAudio`; the processed loudness
 37	    /// measurement (`ProcessedLoudness.render`, spec §11 AU-64 (d)) calls it
 38	    /// directly, so a clip is measured through the very files it exports
 39	    /// with. Never main.
 40	    static func withOfflineAudio<T>(
 41	        plan: CompositionPlan, urls: [UInt32: URL], key: Int,
 42	        cancelled: @escaping () -> Bool, then build: () throws -> T
 43	    ) throws -> T {
 44	        try waitForLevels(plan: plan, key: key, cancelled: cancelled)
 45	        let ramped = plan.audioTracks.contains(where: { $0.segments.contains { $0.ramp != nil } })
 46	        let dsp = AudioDSPSource.shared.parameters(for: key)
 47	        let segments = plan.audioTracks.lazy.flatMap(\.segments)
 48	        let isolated = segments.contains {
 49	            dsp.wantsIsolation($0.clip) && IsolationCache.isolatable($0)
 50	        }
 51	        let voiced = segments.contains {
 52	            dsp.voice(for: $0.clip) != nil && IsolationCache.isolatable($0)
 53	        }
 54	        guard ramped || isolated || voiced else { return try build() }
 55	        let reverse = ReverseSource.shared.resolution(for: key)
 56	        if ramped, reverse.rampAudio == nil,
 57	            let orphan = segments.first(where: {
 58	                $0.ramp != nil && $0.duration > 0 && urls[$0.media] != nil
 59	                    && !reverse.pending.contains($0.clip)
 60	            })
 61	        {
 62	            throw ExportError.rampAudioFailed(
 63	                clip: orphan.clip, message: "the project has no cache folder to render it into")
 64	        }
 65	        if isolated, reverse.isolated == nil,
 66	            let orphan = segments.first(where: {
 67	                dsp.wantsIsolation($0.clip) && IsolationCache.isolatable($0)
 68	                    && urls[$0.media] != nil && !reverse.pending.contains($0.clip)
 69	            })
 70	        {
 71	            throw ExportError.isolationFailed(
 72	                clip: orphan.clip, message: "the project has no cache folder to render it into")
 73	        }
 74	        if voiced, reverse.voiced == nil,
 75	            let orphan = segments.first(where: {
 76	                dsp.voice(for: $0.clip) != nil && IsolationCache.isolatable($0)
 77	                    && urls[$0.media] != nil && !reverse.pending.contains($0.clip)
 78	            })
 79	        {
 80	            throw ExportError.voiceFailed(
 81	                clip: orphan.clip, message: "the project has no cache folder to render it into")
 82	        }
 83	        let requests = RampAudioCache.requests(plan: plan, urls: urls, reverse: reverse)
 84	            + IsolationCache.requests(plan: plan, dsp: dsp, urls: urls, reverse: reverse)
 85	        if !requests.isEmpty {
 86	            try wait(for: requests, wanting: requests, key: key, cancelled: cancelled)
 87	        }
 88	        if voiced {
 89	            let voices = VoiceCache.requests(plan: plan, dsp: dsp, urls: urls, reverse: reverse)
 90	            if !voices.isEmpty {
 91	                try wait(for: voices, wanting: requests + voices, key: key, cancelled: cancelled)
 92	            }
 93	        }
 94	        return try build()
 95	    }
