 97	    /// Wants `wanting` under `key` (a want replaces the owner's set) and
 98	    /// waits for `requests`, a failure thrown as its job's error.
 99	    private static func wait(
100	        for requests: [RampAudioRequest], wanting: [RampAudioRequest], key: Int,
101	        cancelled: @escaping () -> Bool
102	    ) throws {
103	        RampAudioRenders.shared.want(wanting, owner: key, settled: nil)
104	        do {
105	            try RampAudioRenders.shared.wait(for: requests, owner: key, cancelled: cancelled)
106	        } catch RampAudioRenders.WaitError.failed(let request, let message) {
107	            switch request.job {
108	            case .ramp:
109	                throw ExportError.rampAudioFailed(clip: request.clip, message: message)
110	            case .isolation:
111	                throw ExportError.isolationFailed(clip: request.clip, message: message)
112	            case .voice:
113	                throw ExportError.voiceFailed(clip: request.clip, message: message)
114	            }
115	        } catch {
116	            throw ExportError.cancelled
117	        }
118	    }
