120	    /// Waits for the level of every gated or de-essed clip that plays and is
121	    /// still pending (AU-42), up to `AudioDynamicsLevels.exportTimeout`; then
122	    /// fails `loudnessUnmeasured` naming the first, or `cancelled`. A clip
123	    /// that will never be measured (under 0.4 s, silent) is not pending and
124	    /// exports ungated, as the preview plays it.
125	    static func waitForLevels(
126	        plan: CompositionPlan, key: Int, cancelled: @escaping () -> Bool
127	    ) throws {
128	        let pending = AudioDSPSource.shared.parameters(for: key).pendingLevels
129	        guard !pending.isEmpty, let project = RecipeSource.shared.project(for: key) else { return }
130	        let playing = Set(
131	            plan.audioTracks.lazy.flatMap(\.segments)
132	                .filter { $0.duration > 0 && pending.contains($0.clip) }.map(\.clip))
133	        guard !playing.isEmpty else { return }
134	        switch AudioDynamicsLevels.shared.wait(
135	            for: playing, in: project, cache: ReverseSource.shared.resolution(for: key).cache,
136	            timeout: AudioDynamicsLevels.exportTimeout, cancelled: cancelled)
137	        {
138	        case .landed: return
139	        case .cancelled: throw ExportError.cancelled
140	        case .timedOut(let clip): throw ExportError.loudnessUnmeasured(clip: clip)
141	        }
142	    }
